link.script:
function loadGTM() {
    (function (w, d, s, l, i) {
        w[l] = w[l] || [];
        w[l].push({
            'gtm.start': new Date().getTime(),
            event: 'gtm.js'
        });
        var f = d.getElementsByTagName(s)[0],
            j = d.createElement(s),
            dl = l != 'dataLayer' ? '&l=' + l : '';
        j.async = true;
        j.src = 'https://www.googletagmanager.com/gtm.js?id=' + i + dl;
        f.parentNode.insertBefore(j, f);
    })(window, document, 'script', 'dataLayer', 'GTM-TLX2DNCV');
}

if ('requestIdleCallback' in window) {
    requestIdleCallback(loadGTM, { timeout: 1500 });
} else {
    setTimeout(loadGTM, 1500);
}

body.script:
if ('requestIdleCallback' in window) {
    requestIdleCallback(function() {
        var globalbot = document.createElement('script');
        globalbot.src = 'https://globalbot.ai/init/1/6294F8DDF5D9E6385CAF679B518BF724-14A1-47E3-A955-2B231616E600';
        globalbot.async = true;
        document.body.appendChild(globalbot);
    }, {
        timeout: 3000
    });
} else {
    setTimeout(function() {
        var globalbot = document.createElement('script');
        globalbot.src = 'https://globalbot.ai/init/1/6294F8DDF5D9E6385CAF679B518BF724-14A1-47E3-A955-2B231616E600';
        globalbot.async = true;
        document.body.appendChild(globalbot);
    }, 3000);
}

(function() {
    function loadVLibras() {
        var s = document.createElement('script');
        s.src = 'https://vlibras.gov.br/app/vlibras-plugin.js';
        s.onload = function() {
            if (!window.VLibras || !window.VLibras.Widget) return;

            new window.VLibras.Widget('https://vlibras.gov.br/app');

            if (typeof window.onload === 'function') {
                window.onload();
            }

            setTimeout(function() {
                document.querySelectorAll('[vw] img[data-src]').forEach(function(img) {
                    if (!img.getAttribute('src') || img.naturalWidth === 0) {
                        img.src = 'https://www.vlibras.gov.br/app/' + img.getAttribute('data-src');
                    }
                });
            }, 600);
        };
        document.body.appendChild(s);
    }

    if (document.readyState === 'complete') {
        loadVLibras();
    } else {
        window.addEventListener('load', loadVLibras);
    }
})();

script:
 /* Fallback responsive banner images: force mobile asset on small viewports
and handle Swiper clones via MutationObserver. */
 (function() {
     var mq = window.matchMedia('(max-width: 991px)');

     function updateBannerImages() {
         var imgs = document.querySelectorAll('.slide-bg-full__picture img[data-mobile-src]');
         var isMobile = mq.matches;
         imgs.forEach(function(img) {
             var mobile = img.getAttribute('data-mobile-src');
             var desktop = img.getAttribute('data-desktop-src') || img.getAttribute('src');
             var target = isMobile ? mobile : desktop;
             if (!target) return;
             // Only update if different to avoid reload flicker
             try {
                 var current = img.getAttribute('src');
                 if (current !== target) {
                     img.setAttribute('src', target);
                     img.setAttribute('srcset', target);
                 }
             } catch (e) {
                 /* ignore */ }
         });
     }

     document.addEventListener('DOMContentLoaded', function() {
         updateBannerImages();
         var wrapper = document.querySelector('.swiperBannerHome .swiper-wrapper');
         if (wrapper) {
             var mo = new MutationObserver(function() {
                 updateBannerImages();
             });
             mo.observe(wrapper, {
                 childList: true,
                 subtree: true,
                 attributes: true
             });
         }
         window.addEventListener('resize', function() {
             setTimeout(updateBannerImages, 120);
         });
     });
 })();
